import base64,csv,hashlib,io,json,subprocess,sys,tarfile
from pathlib import Path
raw=base64.b64decode('')
if hashlib.sha256(raw).hexdigest()!='f3db89064e18a924fc20c6f7e5c6da6b0f32747ab7a35145bc3b6ff26f169de5': raise RuntimeError('source archive mismatch')
root=Path('/kaggle/temp/raw-diagnostic-src');root.mkdir(parents=True,exist_ok=True)
with tarfile.open(fileobj=io.BytesIO(raw),mode='r:') as f:f.extractall(root,filter='data')
sys.path.insert(0,str(root/'packages/ekido_core'))
from ekido_core.recipes import recipe,passes,eval_set_hash
from transformers import AutoTokenizer
test=root/'experiments/recipes/ticket-sorter-hinglish/test.csv'
with test.open(encoding='utf-8',newline='') as f: rows=list(csv.DictReader(f))
reports=list(Path('/kaggle/input').rglob('summary.json'))
reports=[p for p in reports if 'quantizations' in json.loads(p.read_text(encoding='utf-8'))]
if len(reports)!=1:raise RuntimeError('expected exactly one completed export summary')
source=reports[0].parent;prior=json.loads(reports[0].read_text(encoding='utf-8'))
if eval_set_hash('ticket-sorter-hinglish',rows)!=prior['reference_eval_set_hash']:raise RuntimeError('test hash mismatch')
tok=AutoTokenizer.from_pretrained('Qwen/Qwen2.5-1.5B-Instruct',revision='989aa7980e4cf806f80c7fef2b1adb7bc71aa306')
r=recipe('ticket-sorter-hinglish');prompts=[r.prompt(row['text']) for row in rows]
if any(len(tok(p,add_special_tokens=False)['input_ids'])>508 for p in prompts):raise RuntimeError('prompt exceeds trainer limit')
llama=Path('/kaggle/temp/llama.cpp')
subprocess.run(['git','init',str(llama)],check=True)
subprocess.run(['git','-C',str(llama),'fetch','--depth','1','https://github.com/ggml-org/llama.cpp.git','f8caa5ea30b5775512906ae3b7ee53b21a7a6e1d'],check=True)
subprocess.run(['git','-C',str(llama),'checkout','--detach','FETCH_HEAD'],check=True)
subprocess.run(['cmake','-S',str(llama),'-B',str(llama/'build'),'-DGGML_CUDA=OFF','-DLLAMA_CURL=OFF','-DLLAMA_BUILD_TESTS=OFF'],check=True)
subprocess.run(['cmake','--build',str(llama/'build'),'--target','llama-completion','-j','2'],check=True)
binary=llama/'build/bin/llama-completion'
out=Path('/kaggle/working/raw-diagnostic');out.mkdir(parents=True,exist_ok=True)
summary={'llama_cpp_revision':'f8caa5ea30b5775512906ae3b7ee53b21a7a6e1d','eval_set_hash':prior['reference_eval_set_hash'],
         'reference_pass_rate':prior['reference_pass_rate'],'previous':{},'raw_completion':{}}
for quant in ('Q4_K_M','Q8_0'):
    model=source/('model-'+quant+'.gguf')
    if not model.is_file():raise RuntimeError('missing '+str(model))
    h=hashlib.sha256()
    with model.open('rb') as f:
        for chunk in iter(lambda:f.read(4*1024*1024),b''):h.update(chunk)
    if h.hexdigest()!=prior['quantizations'][quant]['gguf_sha256']:raise RuntimeError('model hash mismatch')
    answers=[]
    for i,(row,prompt) in enumerate(zip(rows,prompts)):
        cmd=[str(binary),'-m',str(model),'-p',prompt,'-n',str(r.max_answer_tokens),'--temp','0',
             '--no-conversation','--no-display-prompt','--no-warmup','--simple-io','-c','512']
        proc=subprocess.run(cmd,capture_output=True,text=True,timeout=120,stdin=subprocess.DEVNULL)
        if proc.returncode:raise RuntimeError('llama-completion failed: '+proc.stderr[-1000:])
        answer=proc.stdout.strip()
        if not answer:raise RuntimeError('no answer returned')
        answers.append({'gold':row['label'],'answer':answer,'passed':bool(passes(r.recipe_id,answer,row['label']))})
        if (i+1)%20==0:print(quant,'raw evaluated',i+1,flush=True)
    score=sum(x['passed'] for x in answers)/len(answers)
    summary['previous'][quant]=prior['quantizations'][quant]['pass_rate']
    summary['raw_completion'][quant]={'pass_rate':score,'examples':len(answers),'answers':answers,
        'difference_from_hf':score-prior['reference_pass_rate'],'gguf_sha256':h.hexdigest()}
    (out/'summary.json').write_text(json.dumps(summary,indent=2,ensure_ascii=False),encoding='utf-8')
    print('RAW_RESULT',quant,score,flush=True)
